/* insertInqDoc - Park Kyuyoung */
INSERT INTO SBA200 /* 문서수발신 */ ( INO_DOC_ESNTAL_NO, INO_DOC_TTL_NM, DOC_INO_CN, SNDPTY_ID, ATFINO, UNT_TASKWK_SE_CD, IOBX_SE_CD, DEL_YN, DOC_CSTDY_YN, SNDNG_DT, DSPTCH_INST_NO, RCVR_NM_ENCPT, THRGH_NM, APPA_NM, SPPRTR_NM_ENCPT, ENFC_NM, RCPT_NM, RLS_YN, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT, OFFCS_SGNNG_ATFINO, OFFCS_SGNNG_ATCMFL_MNG_NO ) VALUES ( #{INO_DOC_ESNTAL_NO}, #{INO_DOC_TTL_NM}, #{DOC_INO_CN}, #{SNDPTY_ID}, #{ATFINO}, #{UNT_TASKWK_SE_CD}, #{IOBX_SE_CD}, 'N', 'N', SYSDATE, #{DSPTCH_INST_NO}, C##RG.ENC_B64(#{RCVR_NM_ENCPT}), #{THRGH_NM}, #{APPA_NM}, C##RG.ENC_B64(#{SPPRTR_NM_ENCPT}), #{ENFC_NM}, #{RCPT_NM}, #{RLS_YN}, #{SNDPTY_ID}, SYSDATE, #{SNDPTY_ID}, SYSDATE, #{OFFCS_SGNNG_ATFINO}, #{OFFCS_SGNNG_ATCMFL_MNG_NO} )

