/* deleteInqDoc - Park Kyuyoung */


UPDATE SBA200 SET /*문서수발신*/

DEL_YN = 'Y'

WHERE 1=1
AND INO_DOC_ESNTAL_NO = #{INO_DOC_ESNTAL_NO}

/* updateInqDoc - Song Taesoo */
UPDATE SBA200 SET /* 문서수발신내용 */
INO_DOC_TTL_NM = #{INO_DOC_TTL_NM}, DOC_INO_CN = #{DOC_INO_CN}, RCVR_NM_ENCPT = C##RG.ENC_B64(#{RCVR_NM_ENCPT}), THRGH_NM = #{THRGH_NM}, APPA_NM = #{APPA_NM}, SPPRTR_NM_ENCPT = C##RG.ENC_B64(#{SPPRTR_NM_ENCPT}), ENFC_NM = #{ENFC_NM}, RCPT_NM = #{RCPT_NM}, RLS_YN = #{RLS_YN}, ATFINO = #{ATFINO}, LAST_MDFR_ID = #{LAST_MDFR_ID}, LAST_MDFCN_DT = SYSDATE
WHERE 1=1 AND INO_DOC_ESNTAL_NO = #{INO_DOC_ESNTAL_NO}

/* updatePrslInqDoc - Taesoo Song */


MERGE INTO SBA210 A
USING   DUAL
    ON  (
        A.INO_DOC_ESNTAL_NO = #{INO_DOC_ESNTAL_NO}
    AND A.RCVR_ID           = #{LOGIN_ID}
        )
WHEN MATCHED THEN
    UPDATE SET /* 문서수발신내용 */
        PRSL_DT         =   NVL((
                                SELECT PRSL_DT 
                                FROM SBA210
                                WHERE INO_DOC_ESNTAL_NO = #{INO_DOC_ESNTAL_NO}
                                AND RCVR_ID = #{LAST_MDFR_ID}
                                AND PRSL_DT IS NOT NULL
                                )
                                ,SYSDATE)
    ,   RDCNT_NOCS      =   (SELECT MAX(NVL(RDCNT_NOCS, 0)+1) FROM SBA210
                            WHERE   INO_DOC_ESNTAL_NO = #{INO_DOC_ESNTAL_NO}
                                AND RCVR_ID = #{LAST_MDFR_ID})
    ,   LAST_MDFR_ID    =   #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT   =   SYSDATE
WHEN NOT MATCHED THEN
    INSERT  (
        INO_DOC_ESNTAL_NO
    ,   RCVR_ID
    ,   RCPTN_INST_NO
    ,   PRSL_DT
    ,   RDCNT_NOCS
    ,   FRST_RGTR_ID
    ,   LAST_MDFR_ID)
    VALUES  (
        #{INO_DOC_ESNTAL_NO}
    ,   #{LOGIN_ID}
    ,   #{INST_NO}
    ,   SYSDATE
    ,   1
    ,   #{LOGIN_ID}
    ,   #{LAST_MDFR_ID})

/* updateRcptnInstPrslInqDoc - Taesoo Song */


UPDATE SBA280 SET /* 문서수발신내용 */
PRSL_DT = NVL((SELECT PRSL_DT FROM SBA280 WHERE INO_DOC_ESNTAL_NO = #{INO_DOC_ESNTAL_NO}  AND RCPTN_INST_NO = #{INST_NO}),SYSDATE),
RDCNT_NOCS = (SELECT MAX(NVL(RDCNT_NOCS, 0)+1) FROM SBA280 WHERE INO_DOC_ESNTAL_NO = #{INO_DOC_ESNTAL_NO}  AND RCPTN_INST_NO = #{INST_NO}),
LAST_MDFR_ID = #{LAST_MDFR_ID}, 
LAST_MDFCN_DT = SYSDATE
WHERE 1=1
AND INO_DOC_ESNTAL_NO = #{INO_DOC_ESNTAL_NO}
AND RCPTN_INST_NO = #{INST_NO}

