/* selectOffcsAtfinoInfo - kim.seong.ok */
SELECT 
  B.* 
FROM SAA230 A
JOIN (
  SELECT ATFINO, MAX(MNG_SN) MNG_SN FROM SAB821 GROUP BY ATFINO
) B ON A.ATFINO = B.ATFINO AND A.ATCMFL_MNG_SN = B.MNG_SN
WHERE A.OFFCS_SGNNG_NO = #{OFFCS_SGNNG_NO}


/* selectOffcsAtfinoPath - kim.seong.ok */
SELECT 
  ATFINO,
  MNG_SN,
  STRG_COURS_NM,
  STRG_FILE_NM
FROM SAB881
WHERE 1=1
AND ATFINO = #{OFFCS_SGNNG_ATFINO}
AND MNG_SN = #{OFFCS_SGNNG_ATCMFL_MNG_NO}
